Bash(export MULTIOMICS_CONFIG=config/config_Amir_Sapir_test.yaml && Rscript -e '
library\(targets\)
prot_de <- tar_read\(prot_de_res\)
cat\("Class:", class\(prot_de\), "\\n"\)
cat\("Names:", paste\(names\(prot_de\), collapse=", "\), "\\n"\)
if \(!is.null\(prot_de$tables\)\) {
    cat\("Tables:", paste\(names\(prot_de$tables\), collapse=", "\), "\\n"\)
    for \(nm in names\(prot_de$tables\)\) {
        df <- prot_de$tables[[nm]]
        cat\(sprintf\("  %s: %d rows, cols: %s\\n", nm, nrow\(df\), paste\(names\(df\), collapse=", "\)\)\)
        cat\(sprintf\("  sig \(padj<0.05 or adj.P.Val<0.05\): "\)\)
        if \("padj" %in% names\(df\)\) cat\(sum\(df$padj < 0.05, na.rm=TRUE\), "\\n"\)
        else if \("adj.P.Val" %in% names\(df\)\) cat\(sum\(df$adj.P.Val < 0.05, na.rm=TRUE\), "\\n"\)
        else cat\("N/A\\n"\)
        cat\("  head feature IDs:", paste\(head\(if\("FeatureID" %in% names\(df\)\) df$FeatureID else rownames\(df\), 5\), collapse=", "\), "\\n"\)
    }
} else {
    cat\("No $tables element\\n"\)
    cat\("Structure:\\n"\)
    str\(prot_de, max.level=2\)
}
')
